  "devEnv.netAllowlist": "Solo sitios permitidos (npm, PyPI, GitHub, los sitios del equipo y los sitios que permite cada persona)",
  "devEnv.warningBodySrt": "La IA puede ejecutar cualquier programa en el servidor del equipo, en cualquier chat. Un comando puede leer todas las carpetas del equipo que la persona del chat puede leer. Solo puede escribir en la carpeta del proyecto del chat y en la carpeta personal de esa persona. Un entorno aislado oculta los datos del servidor, sus secretos, las carpetas personales de otras personas y las carpetas que esa persona no puede abrir.\n- Un comando puede enviar datos al exterior a través de los sitios permitidos. GitHub, npm y PyPI aceptan subidas, así que un comando puede enviar todos los archivos que la persona puede leer.\n- Cada persona puede permitir más sitios para sus propios comandos cuando un chat se lo pregunta, o activar Internet completo para sí misma. Entonces un comando de esa persona también puede enviar datos a esos sitios. No hace falta ningún paso de un administrador.\n- Un comando puede copiar un archivo que la persona puede leer a la carpeta del proyecto, donde lo ven más personas.\n- Los archivos que un comando cambia en la carpeta personal de la persona no tienen registro de cambios ni versiones anteriores.\n- Todos los que pueden escribir en la carpeta del proyecto usan la misma carpeta. Un cambio de una persona afecta al siguiente comando de otra.\n- No hay inicios de sesión. Haga git push y comandos similares en su propio ordenador.\n- Una ejecución que usa demasiada memoria se detiene. Los trabajos pesados del equipo esperan en una cola.\n- Los comandos quedan en el registro de actividad.\nEsta función es un experimento y se puede desactivar en cualquier momento.",
