  'speech.local': "En este servidor (privado)",
  'speech.localHint': "El audio permanece en este servidor. Es lento en servidores pequeños (de 10 segundos a un minuto para un clip corto).",
  'speech.localMissing': "La entrada de voz está desactivada: este servidor no tiene {tools}.",
  'speech.mediaTranscripts': "Convertir el sonido de los videos en texto",
  'speech.mediaTranscriptsLocal': "Cuando la IA lee un archivo de video o audio (por ejemplo, la grabación de una reunión), este servidor convierte su sonido en texto. El sonido nunca sale del servidor. Lo hace en partes de {sec, plural, one {# segundo} other {# segundos}}: una lectura convierte lo que cabe en su tiempo y al leer de nuevo se sigue desde ahí.",
  'speech.mediaTranscriptsSmall': "Desactivado de forma predeterminada: este servidor tiene {cores, plural, one {# núcleo de CPU} other {# núcleos de CPU}}, así que convertir el sonido en texto tarda mucho. Un administrador puede activarlo; mientras esté desactivado, la IA ve los fotogramas del video.",
  'speech.mediaTranscriptsSpeedMin': "Medido en este servidor: unos {n, plural, one {# minuto} other {# minutos}} por cada minuto de sonido.",
  'speech.mediaTranscriptsSpeedSec': "Medido en este servidor: unos {n, plural, one {# segundo} other {# segundos}} por cada minuto de sonido.",
  'speech.mediaTranscriptsHosted': "En este servidor alojado una lectura convierte en texto como máximo {min, plural, one {# minuto} other {# minutos}} de sonido nuevo.",
  'speech.mediaTranscriptsOpenRouter': "Cuando la IA lee un archivo de video o audio (grabaciones de reuniones, llamadas de clientes, videos de formación), su sonido se envía a OpenRouter y a su proveedor para convertirlo en texto. Es un material distinto de la entrada de voz. Se solicita no conservar los datos, pero no podemos garantizarlo. No se envía nada desde chats confidenciales.",
  'speech.privacy': "El audio se envía a OpenRouter y a su proveedor; se solicita retención cero de datos.",
  'speech.model': "Modelo",
  'speech.key': "Clave de API de OpenRouter",
  'speech.keySet': "Hay una clave configurada (…{hint}).",
  'speech.keyNone': "Aún no hay clave. La entrada de voz seguirá desactivada hasta que añada una.",
  'speech.getKey': "Obtener una clave en openrouter.ai/keys",
  'speech.price': "OpenRouter cuesta alrededor de $0.1 por hora de grabación.",
  'speech.saveKey': "Guardar clave",
  'speech.removeKey': "Eliminar clave",
  'speech.removeConfirm': "¿Eliminar la clave de OpenRouter? La entrada de voz se detendrá hasta que añada otra.",
  'speech.keySaved': "Clave guardada",
  'speech.keyRemoved': "Clave eliminada",
  'speech.mediaTranscriptsHostedKey': "Cuando la IA lee un archivo de video o audio (por ejemplo, la grabación de una reunión), la transcripción alojada de Trina convierte su sonido en texto: va a través de OpenRouter a DeepInfra en EE. UU. (Groq si DeepInfra no está disponible), y ninguno conserva los datos. Usa las mismas horas gratuitas que la entrada de voz. No se envía nada desde un chat confidencial.",
  'speech.privacyHosted': "La voz va a través de OpenRouter a DeepInfra en EE. UU. (Groq si DeepInfra no está disponible) para convertirse en texto, y solo a proveedores que no conservan datos (retención cero de datos).",
