  'teamSettings.personalIntegrationsHint': "Permite conectar cuentas propias en Configuración › Apps conectadas. Desactivado: no se pueden añadir nuevas conexiones y las personales existentes quedan fuera de los chats. No afecta a las conexiones del equipo.",
  'teamSettings.aiVision': "Enviar imágenes, páginas PDF y fotogramas de video a la IA",
  'teamSettings.aiVisionHint': "Cuando la IA lee una foto, una captura de pantalla, una página PDF escaneada o un video, ve la imagen directamente, como en Claude Code (en un video, fotogramas repartidos por igual). Las imágenes se envían al proveedor de IA (Anthropic u OpenAI) como cualquier otro contenido de archivos. Desactivado: no se envían imágenes; en un servidor Mac la IA recibe el texto reconocido y en un servidor Linux solo un aviso. En servidores Linux los documentos escaneados no se pueden buscar como texto.",
  'teamSettings.aiSubagents': "Permitir que la IA divida el trabajo en subtareas",
  'teamSettings.aiSubagentsHint': "Como en Claude Code, la IA puede encargar partes de una solicitud grande a IA auxiliares que trabajan a la vez (hasta 4). Cada auxiliar tiene las mismas herramientas y solo ve lo que la persona puede ver; sus pasos aparecen bajo la respuesta y el registro de auditoría guarda sus llamadas. Las auxiliares también usan el servicio de IA, así que una solicitud grande puede costar más. Desactivado: la IA hace todo el trabajo sola.",
  'teamSettings.answerStepLimit': "Rondas de herramientas por respuesta",
  'teamSettings.answerStepLimitHint': "Cuántas veces puede usar herramientas la IA en una respuesta ({min}–{max}, {def} por defecto). Las que usa a la vez cuentan como una. Al agotarse, la respuesta se pausa y «Continuar» la retoma. Con un límite más alto, una respuesta puede trabajar más tiempo y costar más. El límite de 20 minutos y los presupuestos siguen aplicándose. Se aplica a las respuestas de Claude Code.",
  'teamSettings.deckTier': 'Tiempo de la presentación corporativa',
  'teamSettings.deckTierHint': 'Más tiempo lee más del sitio web y busca artículos con fuente para reunir más datos, pero usa más IA (5 minutos, unas 1,5–2 veces los 3 minutos; 10 minutos, unas 2,5–3,5 veces). Mientras se hace, se puede seguir con otras cosas.',
